//! The emission contract between the daemon and the translator, both in the
//! one energy-nexus package. `ethos/emission.ethos`, an Emission root,
//! declares the four external calls, each with its own outcome, and
//! `Emittable`; `ethos/emission_signal.ethos`, a Signal over
//! `energy-emission.sock`, carries them and holds Flow's turn ends open as a
//! subscription. Both are generated by ethos-zero into `src/generated/`,
//! and `build.rs` refuses a committed file that differs.
pub mod generated;
pub use generated::emission::*;
pub use generated::emission_signal::*;

/// The authored Signal over the emission socket.
pub const ETHOS: &str = include_str!("../../../ethos/emission_signal.ethos");
impl signal::Contracted for Input {
    const CONTRACT_SOURCE: &'static str = ETHOS;
}

impl Failure {
    /// A failure with no answer from the provider: no status, no retry-after.
    pub fn of(cause: Cause) -> Self {
        Self {
            cause,
            status: Status(None),
            retry_after: RetryAfter(None),
        }
    }
    /// The seconds the provider said to wait, if it said.
    pub fn retry_after_seconds(&self) -> Option<i64> {
        self.retry_after.0.as_ref().map(|seconds| seconds.0)
    }
}
